//@ run-pass
//@ expect-stdout: CRANELIFT_GEO_MIN_PASS
// Minimal reproducer for a Cranelift 16-lane Clifford-style geometric
// product accumulation pattern that regressed in the past.
//
// Expected behavior:
// - `souc run` (self-hosted VM) prints CRANELIFT_GEO_MIN_PASS
// - `souc jit` should also print CRANELIFT_GEO_MIN_PASS
//
// This fixture stays in run-pass as a backend parity regression guard.

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn approx_eq(a: f64, b: f64, tol: f64) -> bool {
    abs_f64(a - b) < tol
}

fn geo_sign(a: i64, b: i64) -> f64 with Mut, Panic, Div {
    var swaps = 0
    var j = 0
    while j < 4 {
        if (b >> j) & 1 != 0 {
            var k = j + 1
            while k < 4 {
                if (a >> k) & 1 != 0 { swaps = swaps + 1 }
                k = k + 1
            }
        }
        j = j + 1
    }
    let common = a & b
    var msign = 1.0
    if (common >> 1) & 1 != 0 { msign = 0.0 - msign }
    if (common >> 2) & 1 != 0 { msign = 0.0 - msign }
    if (common >> 3) & 1 != 0 { msign = 0.0 - msign }
    if swaps % 2 == 0 { return msign }
    return 0.0 - msign
}

fn geo_product(a: [f64], b: [f64]) -> [f64] with Mut, Panic, Div {
    var r0  = 0.0; var r1  = 0.0; var r2  = 0.0; var r3  = 0.0
    var r4  = 0.0; var r5  = 0.0; var r6  = 0.0; var r7  = 0.0
    var r8  = 0.0; var r9  = 0.0; var r10 = 0.0; var r11 = 0.0
    var r12 = 0.0; var r13 = 0.0; var r14 = 0.0; var r15 = 0.0
    var i = 0
    while i < 16 {
        if a[i] != 0.0 {
            var j = 0
            while j < 16 {
                if b[j] != 0.0 {
                    let k = i ^ j
                    let val = geo_sign(i, j) * a[i] * b[j]
                    if k == 0 { r0 = r0 + val }
                    else if k == 1 { r1 = r1 + val }
                    else if k == 2 { r2 = r2 + val }
                    else if k == 3 { r3 = r3 + val }
                    else if k == 4 { r4 = r4 + val }
                    else if k == 5 { r5 = r5 + val }
                    else if k == 6 { r6 = r6 + val }
                    else if k == 7 { r7 = r7 + val }
                    else if k == 8 { r8 = r8 + val }
                    else if k == 9 { r9 = r9 + val }
                    else if k == 10 { r10 = r10 + val }
                    else if k == 11 { r11 = r11 + val }
                    else if k == 12 { r12 = r12 + val }
                    else if k == 13 { r13 = r13 + val }
                    else if k == 14 { r14 = r14 + val }
                    else if k == 15 { r15 = r15 + val }
                }
                j = j + 1
            }
        }
        i = i + 1
    }
    return [r0, r1, r2, r3, r4, r5, r6, r7,
            r8, r9, r10, r11, r12, r13, r14, r15]
}

fn mv_basis(idx: i64) -> [f64] with Mut, Panic, Div {
    var r0  = 0.0; var r1  = 0.0; var r2  = 0.0; var r3  = 0.0
    var r4  = 0.0; var r5  = 0.0; var r6  = 0.0; var r7  = 0.0
    var r8  = 0.0; var r9  = 0.0; var r10 = 0.0; var r11 = 0.0
    var r12 = 0.0; var r13 = 0.0; var r14 = 0.0; var r15 = 0.0
    if idx == 0 { r0 = 1.0 }
    else if idx == 1 { r1 = 1.0 }
    else if idx == 2 { r2 = 1.0 }
    else if idx == 3 { r3 = 1.0 }
    else if idx == 4 { r4 = 1.0 }
    else if idx == 5 { r5 = 1.0 }
    else if idx == 6 { r6 = 1.0 }
    else if idx == 7 { r7 = 1.0 }
    else if idx == 8 { r8 = 1.0 }
    else if idx == 9 { r9 = 1.0 }
    else if idx == 10 { r10 = 1.0 }
    else if idx == 11 { r11 = 1.0 }
    else if idx == 12 { r12 = 1.0 }
    else if idx == 13 { r13 = 1.0 }
    else if idx == 14 { r14 = 1.0 }
    else if idx == 15 { r15 = 1.0 }
    return [r0, r1, r2, r3, r4, r5, r6, r7,
            r8, r9, r10, r11, r12, r13, r14, r15]
}

fn test_full_metric() -> bool with Mut, Panic, Div {
    let e0_sq = geo_product(mv_basis(1), mv_basis(1))
    let e1_sq = geo_product(mv_basis(2), mv_basis(2))
    let e2_sq = geo_product(mv_basis(4), mv_basis(4))
    let e3_sq = geo_product(mv_basis(8), mv_basis(8))
    return approx_eq(e0_sq[0], 1.0, 1.0e-10)
        && approx_eq(e1_sq[0], 0.0 - 1.0, 1.0e-10)
        && approx_eq(e2_sq[0], 0.0 - 1.0, 1.0e-10)
        && approx_eq(e3_sq[0], 0.0 - 1.0, 1.0e-10)
}

fn main() -> i32 with IO, Mut, Panic, Div {
    if test_full_metric() {
        println("CRANELIFT_GEO_MIN_PASS")
        return 0
    }
    println("CRANELIFT_GEO_MIN_FAIL")
    return 1
}

//@ run-pass
//@ expect-stdout-contains: PBPK28_ORGAN_SINK_CN_PASS
//
// Organ sink inside the PBPK28 CN step (pbpk28_full_cn_step_sink_mut), on the
// venlafaxine parent profile with the CYP2D6 formation clearance on the liver.
// Imports only the kernel + params, in darwin_pbpk28_smoke's style, so it also
// runs under Madaros (scenarios/venlafaxine_xr pulls in release/matrix_er,
// which the Madaros checker currently segfaults on).
//
// 75 mg oral dose from a gut pool (ka = 0.63 /h), dt = 0.5 h, 48 h;
// CL_form = 43 · r / 3.45 L/h (Klamerus 1999 NM value scaled by Kirchheiner
// 2006 ODV/parent ratios r, as in pgx/cyp2d6_venlafaxine), CL_central = 57 L/h.
// CL_form·dt/V_liver spans 0.87 (PM) .. 35.7 (UM). Checks:
//   1. Per-step mass identity M_new = M_old + dt·input
//      − h·CL_c·(C_b,old + C_b,new) − removed, on every step where no state
//      was clamped; exact in the CN algebra, so tolerance = rounding (1e-12 mg).
//   2. Cumulative formation strictly increases PM < IM < NM < UM (an explicit
//      post-step sink capped at the liver content forms identical mass for
//      IM, NM and UM at this dt).
//   3. With no sink the step is bit-identical to pbpk28_full_cn_step AND to a
//      frozen verbatim copy of the pre-PR kernel (independent reference).

use darwin_pbpk::core::pbpk28_params::*
use darwin_pbpk::tsit5_pbpk28::*

// FROZEN REFERENCE (Copilot review on #2699): the sink-free kernel exactly as
// it stood on main before this PR (origin/main f141ad5d9, tsit5_pbpk28.sio),
// copied verbatim apart from the two names. Check 3 compares the new
// sink-off path against THIS copy, so a drift in the shared arithmetic cannot
// hide behind the wrapper delegating to the routine under test.
fn frz_apply_schur(
    state: &!PBPKState28,
    cb_new: f64,
    a_v: &[f64; 14],
    b_v: &[f64; 14],
    a_t: &[f64; 14],
    b_t: &[f64; 14]
) with Mut, Div {
    (*state).cv[0] = if cb_new < 0.0 { 0.0 } else { cb_new }
    var i: i32 = 1
    while i < 14 {
        let cv = (*a_v)[i] + (*b_v)[i] * cb_new
        let ct = (*a_t)[i] + (*b_t)[i] * cb_new
        (*state).cv[i] = if cv < 0.0 { 0.0 } else { cv }
        (*state).ct[i] = if ct < 0.0 { 0.0 } else { ct }
        i = i + 1
    }
}

fn frz_cn_step_mut(state: &!PBPKState28, p: PBPKParams28, rel_mid: f64, dt: f64) with Mut, Div {
    var a_v: [f64; 14] = [0.0; 14]
    var b_v: [f64; 14] = [0.0; 14]
    var a_t: [f64; 14] = [0.0; 14]
    var b_t: [f64; 14] = [0.0; 14]
    let h = 0.5 * dt
    let vb = p.v_ref[0]

    // Big-S = h · (Σ Q + CL) / V_b — diagonal of the blood row.
    var sum_q = 0.0
    var i: i32 = 1
    while i < 14 {
        sum_q = sum_q + p.q[i]
        i = i + 1
    }
    let big_s = h * (sum_q + p.cl_central) / vb

    let cb_old = (*state).cv[0]
    var rhs0 = (1.0 - big_s) * cb_old + dt * rel_mid / vb

    // Per-organ Schur-complement coefficients.
    var sum_beta_a = 0.0
    var sum_beta_b = 0.0

    i = 1
    while i < 14 {
        let vi = p.v_ref[i]
        let vf = p.vasc_frac[i]
        let vv_raw = vi * vf
        let vt_raw = vi * (1.0 - vf)
        // Floor to avoid division by zero in degenerate (vasc_frac=0 or =1)
        // configurations — used by case 2 of the parity gate (PBPK28 → QSS).
        let vv = if vv_raw < 1.0e-30 { 1.0e-30 } else { vv_raw }
        let vt = if vt_raw < 1.0e-30 { 1.0e-30 } else { vt_raw }
        let kp = p.kp[i]
        let ps = p.ps[i]
        let qi = p.q[i]

        let beta  = h * qi / vb
        let gamma = h * qi / vv
        let pp    = 1.0 + h * (qi + ps) / vv
        let qq    = h * ps / (vv * kp)
        let rr    = h * ps / vt
        let sb    = 1.0 + h * ps / (vt * kp)
        let det   = pp * sb - qq * rr

        rhs0 = rhs0 + beta * (*state).cv[i]

        let rhs_v = gamma * cb_old + (1.0 - h * (qi + ps) / vv) * (*state).cv[i] + qq * (*state).ct[i]
        let rhs_t = rr * (*state).cv[i] + (1.0 - h * ps / (vt * kp)) * (*state).ct[i]

        let av = (sb * rhs_v + qq * rhs_t) / det
        let bv = (sb * gamma) / det
        let at = (rr * rhs_v + pp * rhs_t) / det
        let bt = (rr * gamma) / det

        a_v[i] = av
        b_v[i] = bv
        a_t[i] = at
        b_t[i] = bt

        sum_beta_a = sum_beta_a + beta * av
        sum_beta_b = sum_beta_b + beta * bv
        i = i + 1
    }

    // Close the step: scalar equation for C_b_new.
    let cb_new = (rhs0 + sum_beta_a) / ((1.0 + big_s) - sum_beta_b)
    frz_apply_schur(state, cb_new, &a_v, &b_v, &a_t, &b_t)
}

fn fmt_9(x: f64) -> i64 { return (x * 1000000000.0) as i64 }

fn main() with Mut, Div, IO {
    let dt = 0.5
    let h = 0.5 * dt
    let frac = 0.2702133 // 1 − exp(−0.63 · 0.5), literal so both engines share it
    var pheno = 0
    var prev_formed = 0.0 - 1.0
    var order_ok = true
    while pheno < 4 {
        var r = 3.45
        if pheno == 0 { r = 0.25 }
        if pheno == 1 { r = 1.16 }
        if pheno == 3 { r = 10.3 }
        let clf = 43.0 * (r / 3.45)
        var pp = pbpk28_params_venlafaxine_parent()
        pp.cl_central = 57.0
        var par = pbpk28_state_zero()
        var gut = 75.0
        var formed = 0.0
        var max_res = 0.0
        var k = 0
        while k < 96 {
            let ab = gut * frac
            gut = gut - ab
            let m0 = pbpk28_total_mass(par, pp)
            let c0 = par.cv[0]
            let form = pbpk28_full_cn_step_sink_mut(&!par, pp, ab / dt, dt, 1, clf)
            let m1 = pbpk28_total_mass(par, pp)
            formed = formed + form
            var zeroed = par.cv[0] == 0.0
            var i = 1
            while i < 14 {
                if par.cv[i] == 0.0 || par.ct[i] == 0.0 { zeroed = true }
                i = i + 1
            }
            if !zeroed {
                var res = m1 - (m0 + ab - h * pp.cl_central * (c0 + par.cv[0]) - form)
                if res < 0.0 { res = 0.0 - res }
                if res > max_res { max_res = res }
            }
            k = k + 1
        }
        print("pheno="); print(pheno)
        print(" formed_mg*1e9="); print(fmt_9(formed))
        print(" max_res_unclamped_mg*1e9="); println(fmt_9(max_res))
        if !(formed > prev_formed) { order_ok = false }
        if !(max_res < 1.0e-12) { order_ok = false }
        prev_formed = formed
        pheno = pheno + 1
    }
    if !order_ok {
        println("FAIL: organ-sink identity or phenotype ordering")
        return
    }

    var p0 = pbpk28_params_venlafaxine_parent()
    p0.cl_central = 57.0
    var s1 = pbpk28_state_zero()
    var s2 = pbpk28_state_zero()
    var s3 = pbpk28_state_zero()
    var j = 0
    while j < 20 {
        var rel = 0.0
        if j < 6 { rel = 5.0 }
        let removed = pbpk28_full_cn_step_sink_mut(&!s1, p0, rel, 0.5, 0, 0.0)
        s2 = pbpk28_full_cn_step(s2, p0, rel, 0.5)
        frz_cn_step_mut(&!s3, p0, rel, 0.5)
        if removed != 0.0 {
            println("FAIL: sink-off step reported removed mass")
            return
        }
        var i = 0
        while i < 14 {
            if s1.cv[i] != s2.cv[i] || s1.ct[i] != s2.ct[i] {
                println("FAIL: sink-off step differs from pbpk28_full_cn_step")
                return
            }
            if s1.cv[i] != s3.cv[i] || s1.ct[i] != s3.ct[i] {
                println("FAIL: sink-off step differs from the frozen pre-PR kernel")
                return
            }
            i = i + 1
        }
        j = j + 1
    }
    println("PBPK28_ORGAN_SINK_CN_PASS")
}

