fn emit_polyline(
    x_data: &[f64; 1024],
    y_data: &[f64; 1024],
    n: i64,
    ox: i64, oy: i64,
    plot_w: i64, plot_h: i64,
    x_min: f64, x_max: f64,
    y_min: f64, y_max: f64,
    color: string,
) with IO, Mut, Panic, Div {
    let x_range = x_max - x_min
    let y_range = y_max - y_min

    print("<polyline fill=\"none\" stroke=\"")
    print(color)
    print("\" stroke-width=\"2\" stroke-linejoin=\"round\" points=\"")

    var i: i64 = 0
    while i < n {
        var px: f64 = 0.0
        if x_range > 0.0 { px = ox as f64 + ((x_data[i] - x_min) / x_range) * plot_w as f64 }
        else { px = ox as f64 + plot_w as f64 / 2.0 }
        var py: f64 = 0.0
        if y_range > 0.0 { py = oy as f64 - ((y_data[i] - y_min) / y_range) * plot_h as f64 }
        else { py = oy as f64 - plot_h as f64 / 2.0 }

        svg_print_f64(px, 1)
        print(",")
        svg_print_f64(py, 1)

        if i < n - 1 {
            print(" ")
        }
        i = i + 1
    }
    println("\"/>")
}

